    private void executeScannerTask() {

        HomeBankingLoadDTO homeBankingLoadDTO = performDataBase.loadHomeBanking(this.botJobLoad.getHomeBankingId());

        if (this.botJobLoad.getBlockLoadDTOList() != null
                && this.botJobLoad.getBlockLoadDTOList().size() > 0) {
            this.blockLoad = this.botJobLoad.getBlockLoadDTOList().get(0);
        } else {

            this.blockLoadList = performDataBase.loadBlocksByBotJobId(this.botJobLoad.getId());
            if (this.blockLoadList.size() > 0) {
                this.blockLoad = blockLoadList.get(0);
            }
        }

        try {
            Platform.runLater(() -> {
                try {

                    activeSessions = SimpleWebSocketServer.getAllSessions();
                    // Call the ARScannedElementScene here
                    ARScannedElementScene scene = arScannedElementScene.initialize(
                            arWebDriver,
                            performDataBase,
                            performActions,
                            performMessage,
                            performPreLoad,
                            homeBankingLoadDTO,
                            this.botJobLoad,
                            this.blockLoad);

                    scene.show(); // Make sure the scene is shown
                } catch (Exception ex) {
                    handleExceptionScan(ex);
                }
            });
        } catch (Exception ex) {
            handleExceptionScan(ex);
        }
    }

    private void handleExceptionScan(Exception error) {
        // Log the exception
        ARLogger.getInstance(ARViewBotJobPane.class)
                .severe("ERROR Calling openScannerButton -> Cause: " + error.getMessage());

        // Display the error message to the user
        if (error.getMessage().contains("no such window: target window already closed")
                || error.getMessage().contains("web view not found")) {
            performMessage.errorMessage(
                    "Error Calling SCAN",
                    "Web Browser was closed before the Scanner Tool",
                    "Close and Re-Open the Scanner Tool",
                    null,
                    null,
                    0);
        } else {

            //            "invalid session id"

            if (!error.getMessage().contains("Current browser version")) {
                String[] lines = error.getMessage().split("\n");

                String msg1 = null;
                String msg2 = null;
                String msg3 = null;
                String msg4 = null;

                for (String line : lines) {
                    // Exclude unnecessary lines
                    if (line.contains("Host info")
                            || line.contains("Build info")
                            || line.contains("System info")
                            || line.contains("Command")) {
                        continue;
                    }

                    String message = line.contains("Message: ")
                            ? line.substring(line.indexOf("Message: ") + "Message: ".length())
                                    .trim()
                            : line.trim();

                    if (!message.isEmpty()) {
                        if (msg1 == null) {
                            msg1 = message;
                        } else if (msg2 == null) {
                            msg2 = message;
                        } else if (msg3 == null) {
                            msg3 = message;
                        } else if (msg4 == null) {
                            msg4 = message;
                        }
                    }
                }

                ARLogger.getInstance(ARViewBotJobPane.class).severe("Error Open URL: \n" + msg1 + "\n" + msg2);

                performMessage.errorMessage("Error Open URL", msg1, msg2, msg3, msg4, 0);
            }
        }

        //        Platform.runLater(() -> {
        //            JOptionPane.showMessageDialog(
        //                    null,
        //                    "An error has occurred Calling SCAN: \nCause: " + ex.getMessage(),
        //                    "Error calling in SCAN",
        //                    JOptionPane.ERROR_MESSAGE);
        //        });
    }

    private void showAlert(String title, String content) {
        executorService = Executors.newSingleThreadExecutor();
        alertToShow.setAlertType(AlertType.ERROR);
        alertToShow.setTitle("Error");
        alertToShow.setHeaderText(title);
        alertToShow.setContentText(content);

        executorService.execute(() -> {
            timeline.setCycleCount(SECONDS); // Run for seconds
            timeline.play(); // Start the timeline

            // Show the alert on the JavaFX Application Thread
            javafx.application.Platform.runLater(() -> alertToShow.showAndWait());
        });

        if (executorService != null) {
            remainingSeconds = SECONDS;
            executorService.shutdown();
        }
    }

